      return await test(rest, stdin, stdout, stderr);

    case 'lint':
      return await lint(rest, stdin, stdout, stderr);

    default:
      throw new Error(`unexpected command: ${args[0]}`);
  }
}

async function build(
  args: Array<string>,
  stdin: NodeJS.ReadStream,
  stdout: NodeJS.WriteStream,
